param(
    [switch]$NoLaunch,
    [switch]$ExtractOnly
)

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'

$GuiHash = 'B9C1CFFC2250C2E5791631C7AF8514A6717B08BA8A518D938752FFB944085058'
$ConsoleHash = 'C85A439D647D9BBE1DAC8A18252C22B58112FDE67855E85C56CDE0C702C213D3'

$GuiPayload = @'

'@

$ConsolePayload = @'

'@

function Convert-GzipPayload([string]$base64) {
    $clean = $base64 -replace '\s', ''
    $compressed = [Convert]::FromBase64String($clean)
    $inputStream = New-Object System.IO.MemoryStream(, $compressed)
    $outputStream = New-Object System.IO.MemoryStream
    try {
        $gz = New-Object System.IO.Compression.GZipStream($inputStream, [System.IO.Compression.CompressionMode]::Decompress)
        try { $gz.CopyTo($outputStream) } finally { $gz.Dispose() }
        return $outputStream.ToArray()
    } finally {
        $inputStream.Dispose()
        $outputStream.Dispose()
    }
}

function Assert-PayloadHash([byte[]]$bytes, [string]$expected) {
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        $actual = ([System.BitConverter]::ToString($sha.ComputeHash($bytes)).Replace('-', '')).ToUpperInvariant()
    } finally { $sha.Dispose() }
    if ($actual -ne $expected) { throw "Embedded payload hash mismatch. Expected $expected, got $actual." }
}

Write-Host ''
Write-Host '  VencordSetup - self-contained bootstrap' -ForegroundColor Cyan
Write-Host '  payloads: GUI + console, SHA-256 verified' -ForegroundColor DarkGray
Write-Host ''

$guiBytes = Convert-GzipPayload $GuiPayload
$consoleBytes = Convert-GzipPayload $ConsolePayload
Assert-PayloadHash $guiBytes $GuiHash
Assert-PayloadHash $consoleBytes $ConsoleHash

$dirName = 'VencordSetup_' + $GuiHash.Substring(0, 12).ToLowerInvariant()
$dir = Join-Path $env:TEMP $dirName
New-Item -ItemType Directory -Path $dir -Force | Out-Null

$guiPath = Join-Path $dir 'VencordSetupGUI.ps1'
$consolePath = Join-Path $dir 'VencordSetup.ps1'
$utf8 = New-Object System.Text.UTF8Encoding($false)
[System.IO.File]::WriteAllText($guiPath, [System.Text.Encoding]::UTF8.GetString($guiBytes), $utf8)
[System.IO.File]::WriteAllText($consolePath, [System.Text.Encoding]::UTF8.GetString($consoleBytes), $utf8)

Write-Host '  verified and extracted:' -ForegroundColor Green
Write-Host ("    " + $guiPath) -ForegroundColor Gray
Write-Host ("    " + $consolePath) -ForegroundColor Gray

if ($NoLaunch -or $ExtractOnly) {
    Write-Host ''
    return
}

Write-Host '  launching GUI...' -ForegroundColor Green
$argLine = '-NoProfile -STA -ExecutionPolicy RemoteSigned -File "' + $guiPath + '"'
$proc = Start-Process -FilePath 'powershell.exe' -ArgumentList $argLine -NoNewWindow -PassThru -Wait
if ($proc.ExitCode -ne 0) {
    throw "GUI exited with code $($proc.ExitCode). See the log above."
}
